import json
import unittest

BLOCKED = "CONNECTION_BLOCKED_PENDING_VERIFICATION"

LOCAL = {
    "pinned": {
        "name": "acme-catalog-mcp",
        "version": "1.4.2",
        "digest": "sha256:111"
    },
    "observed": {
        "name": "acme-catalog-mcp",
        "version": "1.4.2",
        "digest": "sha256:111"
    },
    "tools": ["catalog_search", "catalog_get", "catalog_export"],
    "reviewed_tools": ["catalog_search", "catalog_get", "catalog_export"],
    "network": ["catalog-db.internal.example:5432"],
    "network_allowlist": ["catalog-db.internal.example:5432"],
    "prerequisites": {
        "containment": False,
        "process_policy": False,
        "redaction": False,
        "revocation": False
    }
}

REMOTE = {
    "expected_issuer": "https://issuer.remote.example",
    "observed_issuer": "https://issuer.remote.example",
    "expected_audience": "mcp-catalog",
    "observed_audience": "catalog-api",
    "prerequisites": {
        "containment": False,
        "process_policy": False,
        "redaction": False,
        "revocation": False
    }
}

REMOTE_ALL_TRUE_MISMATCH = {
    "expected_issuer": "https://issuer.remote.example",
    "observed_issuer": "https://issuer.remote.example",
    "expected_audience": "mcp-catalog",
    "observed_audience": "catalog-api",
    "prerequisites": {
        "containment": True,
        "process_policy": True,
        "redaction": True,
        "revocation": True
    }
}

REMOTE_ALL_TRUE_MATCH = {
    "expected_issuer": "https://issuer.remote.example",
    "observed_issuer": "https://issuer.remote.example",
    "expected_audience": "mcp-catalog",
    "observed_audience": "mcp-catalog",
    "prerequisites": {
        "containment": True,
        "process_policy": True,
        "redaction": True,
        "revocation": True
    }
}


def _require_mapping(value, path, required):
    if not isinstance(value, dict):
        raise ValueError(path + " must be an object")
    missing = [key for key in required if key not in value]
    if missing:
        raise ValueError(path + " missing fields: " + ",".join(missing))


def _require_nonempty_string(value, path):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(path + " must be a nonempty string")


def _require_string_list(value, path):
    if not isinstance(value, list):
        raise ValueError(path + " must be a list")
    for index, item in enumerate(value):
        _require_nonempty_string(item, path + "[" + str(index) + "]")


def _validate_identity(identity, path):
    _require_mapping(identity, path, ["name", "version", "digest"])
    for field in ["name", "version", "digest"]:
        _require_nonempty_string(identity[field], path + "." + field)


def load_record(text):
    try:
        record = json.loads(text)
        _require_mapping(record, "record", [])
        return record
    except (TypeError, UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
        return "REJECT | malformed record | " + str(exc)


def records_match(pinned, observed):
    _validate_identity(pinned, "pinned")
    _validate_identity(observed, "observed")
    return pinned == observed


def tools_contained(observed, reviewed):
    _require_string_list(observed, "tools")
    _require_string_list(reviewed, "reviewed_tools")
    return set(observed) <= set(reviewed)


def network_contained(observed, allowlist):
    _require_string_list(observed, "network")
    _require_string_list(allowlist, "network_allowlist")
    return set(observed) <= set(allowlist)


def inspect_local(record):
    _require_mapping(
        record,
        "local record",
        ["pinned", "observed", "tools", "reviewed_tools", "network", "network_allowlist"]
    )
    identity_ok = records_match(record["pinned"], record["observed"])
    tools_ok = tools_contained(record["tools"], record["reviewed_tools"])
    network_ok = network_contained(record["network"], record["network_allowlist"])
    return "RECORDS_MATCH" if identity_ok and tools_ok and network_ok else "REVIEW_REQUIRED"


def inspect_remote(record):
    fields = [
        "expected_issuer",
        "observed_issuer",
        "expected_audience",
        "observed_audience"
    ]
    _require_mapping(record, "remote record", fields)
    for field in fields:
        _require_nonempty_string(record[field], "remote record." + field)
    issuer_ok = record["expected_issuer"] == record["observed_issuer"]
    audience_ok = record["expected_audience"] == record["observed_audience"]
    return "RECORDS_MATCH" if issuer_ok and audience_ok else "REVIEW_REQUIRED"


def connection_decision():
    # This record-inspection toy consumes no independently verified authority evidence.
    return BLOCKED


def inspect_and_decide(record, deployment):
    try:
        if deployment == "local":
            inspection = inspect_local(record)
        elif deployment == "remote":
            inspection = inspect_remote(record)
        else:
            raise ValueError("deployment must be local or remote")
        return inspection, connection_decision()
    except (KeyError, TypeError, ValueError) as exc:
        return "REJECT | malformed or missing record: " + str(exc), connection_decision()


def print_case(name, record, deployment):
    inspection, decision = inspect_and_decide(record, deployment)
    print(name + " " + inspection)
    print(name + " " + decision)


def main():
    print_case("LOCAL", LOCAL, "local")
    print_case("REMOTE", REMOTE, "remote")
    print("NOTE no network, secrets, JWT validation, process launch, live containment test, or authority evidence consumed")
    fixtures = {
        "local": LOCAL,
        "remote": REMOTE,
        "remote_all_true_match": REMOTE_ALL_TRUE_MATCH,
        "remote_all_true_mismatch": REMOTE_ALL_TRUE_MISMATCH
    }
    print("FIXTURES " + json.dumps(fixtures, sort_keys=True))


class TrustReviewTests(unittest.TestCase):
    def test_baseline(self):
        self.assertEqual(inspect_local(LOCAL), "RECORDS_MATCH")
        self.assertEqual(inspect_remote(REMOTE), "REVIEW_REQUIRED")
        self.assertEqual(connection_decision(), BLOCKED)

    def test_all_true_mismatch_still_blocked(self):
        inspection, decision = inspect_and_decide(REMOTE_ALL_TRUE_MISMATCH, "remote")
        self.assertEqual(inspection, "REVIEW_REQUIRED")
        self.assertEqual(decision, BLOCKED)
        self.assertNotIn("APPROVE", decision)

    def test_all_true_match_still_blocked(self):
        inspection, decision = inspect_and_decide(REMOTE_ALL_TRUE_MATCH, "remote")
        self.assertEqual(inspection, "RECORDS_MATCH")
        self.assertEqual(decision, BLOCKED)
        self.assertNotIn("APPROVE", decision)

    def test_changed_digest(self):
        local = dict(LOCAL)
        local["observed"] = dict(LOCAL["observed"], digest="sha256:999")
        self.assertEqual(inspect_local(local), "REVIEW_REQUIRED")

    def test_unreviewed_write(self):
        local = dict(LOCAL)
        local["tools"] = LOCAL["tools"] + ["catalog_write"]
        self.assertEqual(inspect_local(local), "REVIEW_REQUIRED")

    def test_issuer_audience_mismatch(self):
        remote = dict(REMOTE)
        remote["observed_issuer"] = "https://other-issuer.example"
        self.assertEqual(inspect_remote(remote), "REVIEW_REQUIRED")

    def test_malformed_json_controlled_rejection(self):
        result = load_record("{not json")
        self.assertTrue(result.startswith("REJECT | malformed record"))

    def test_missing_record_controlled_rejection(self):
        inspection, decision = inspect_and_decide({}, "local")
        self.assertTrue(inspection.startswith("REJECT | malformed or missing record"))
        self.assertEqual(decision, BLOCKED)

    def test_empty_nested_identity_rejected(self):
        local = dict(LOCAL)
        local["observed"] = dict(LOCAL["observed"], name=" ")
        inspection, decision = inspect_and_decide(local, "local")
        self.assertTrue(inspection.startswith("REJECT | malformed or missing record"))
        self.assertEqual(decision, BLOCKED)

    def test_tools_must_be_list(self):
        local = dict(LOCAL)
        local["tools"] = "catalog_search"
        inspection, decision = inspect_and_decide(local, "local")
        self.assertTrue(inspection.startswith("REJECT | malformed or missing record"))
        self.assertEqual(decision, BLOCKED)

    def test_empty_tool_name_rejected(self):
        local = dict(LOCAL)
        local["tools"] = ["catalog_search", ""]
        inspection, decision = inspect_and_decide(local, "local")
        self.assertTrue(inspection.startswith("REJECT | malformed or missing record"))
        self.assertEqual(decision, BLOCKED)

    def test_network_must_be_list_of_nonempty_strings(self):
        local = dict(LOCAL)
        local["network"] = ["catalog-db.internal.example:5432", 7]
        inspection, decision = inspect_and_decide(local, "local")
        self.assertTrue(inspection.startswith("REJECT | malformed or missing record"))
        self.assertEqual(decision, BLOCKED)

    def test_empty_remote_audience_rejected(self):
        remote = dict(REMOTE)
        remote["observed_audience"] = ""
        inspection, decision = inspect_and_decide(remote, "remote")
        self.assertTrue(inspection.startswith("REJECT | malformed or missing record"))
        self.assertEqual(decision, BLOCKED)


if __name__ == "__main__":
    main()

